(window.LART=window.LART||{})["180-树论/30-最近公共祖先"]="<p>最近公共祖先，<code>least common ancestor</code>，<code>LCA</code>。</p>\n\n<h1>朴素做法</h1>\n<div class=\"blanks\" style=\"height:1em\"></div>\n<h1>树上倍增</h1>\n<h2>dfs预处理</h2>\n<pre><code class=\"language-cpp\">int n, m, s;\nvector&lt;int&gt; edge[N]; \nint d[N];\nint f[20][N]; // 倍增 \n\nvoid dfs(int x, int fa) {\n    d[x] = d[fa] + 1;\n\n    f[0][x] = fa;\n    int lg = log2(d[x]);\n    for (int i = 1; i &lt;= lg; ++i) {\n        f[i][x] = f[i - 1][f[i - 1][x]];\n    }\n\n    for (auto y : edge[x]) {\n        if (y == fa) {\n            continue;\n        }\n        dfs(y, x);\n    }\n}\n</code></pre>\n<h2>bfs预处理</h2>\n\n\n<pre><code class=\"language-cpp\">\nint n, m, s;\nvector&lt;int&gt; edge[N]; \nint d[N];\nint f[20][N]; // 倍增 \n\nvoid bfs() {\n    queue&lt;int&gt; q;\n    q.push(s);\n    d[s] = 1;\n\n    while (q.size()) {\n        int x = q.front();\n        q.pop();\n        for (auto y : edge[x]) {\n            if (d[y]) {\n                continue;\n            }\n            q.push(y);\n            d[y] = d[x] + 1;\n            f[0][y] = x;\n            for (int i = 1; i &lt; 20; ++i) {\n                f[i][y] = f[i - 1][f[i - 1][y]];\n            }\n        }\n    }\n}\n</code></pre>\n\n<h2>求LCA</h2>\n\n\n<pre><code class=\"language-cpp\">int lca(int u, int v) {\n    if (d[u] &gt; d[v]) {\n        swap(u, v);\n    }\n\n    // v 高度比较大\n    // 先跳v\n\n    for (int i = log2(d[v] - d[u]); i &gt;= 0; --i) {\n        if (d[f[i][v]] &gt;= d[u]) { \n            // 要跳的f[i][v]高度 &gt;= u \n            v = f[i][v];\n        }\n    } \n    if (u == v) {\n        return u;\n    }\n\n    for (int i = log2(d[v]); i &gt;= 0; --i) {\n        if (f[i][u] != f[i][v]) { \n            // 要跳的f[i][u]， f[i][v] 是不是一样 \n            u = f[i][u];\n            v = f[i][v];\n        }\n    } \n    return f[0][u];\n}\n\n</code></pre>\n\n<h1>任意两点间距离</h1>\n<p>to be continue</p>\n<div class=\"blanks\" style=\"height:1em\"></div>\n<h1>其它求法</h1>\n\n<h2>重链剖分</h2>\n<p>to be continue</p>\n<h2>Tarjan</h2>\n<h3>前置知识</h3>\n<p>并查集<br />\nto be continue</p>\n<h2>ST表</h2>\n\n<p>to be continue</p>\n\n<h1>树上倍增求其它路径信息</h1>\n<div class=\"blanks\" style=\"height:1em\"></div>\n<h1>判断一个点在另外两个之间的路径上</h1>\n\n<h1>习题</h1>\n<div class=\"blanks\" style=\"height:1em\"></div>\n<table>\n<thead>\n<tr>\n<th>题号</th>\n<th>链接</th>\n<th>备注</th>\n<th>难度</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>P3379</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P3379\">最近公共祖先（LCA）</a></td>\n<td>【模板】</td>\n<td>黄题</td>\n</tr>\n<tr>\n<td>P5836</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P5836\">Milk Visits S</a></td>\n<td>路径点权之和</td>\n<td>黄题</td>\n</tr>\n<tr>\n<td>P5588</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P5588\">小猪佩奇爬树</a></td>\n<td>距离判链</td>\n<td>蓝题</td>\n</tr>\n<tr>\n<td>P3398</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P3398\">仓鼠找 sugar</a></td>\n<td>判断路径相交</td>\n<td>绿题</td>\n</tr>\n<tr>\n<td>P1967</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P1967\">货车运输</a></td>\n<td>最大生成树，树上路径最小值</td>\n<td>蓝题</td>\n</tr>\n<tr>\n<td>CF1108F</td>\n<td><a href=\"https://codeforces.com/contest/1108/problem/F\">MST Unification</a></td>\n<td>每次边权加1，使得mst唯一</td>\n<td>2100/蓝题</td>\n</tr>\n<tr>\n<td>CF609E</td>\n<td><a href=\"https://codeforces.com/contest/609/problem/E\">Minimum spanning tree for each edge</a></td>\n<td>每条作为生成树时，mst是多少</td>\n<td>2100/蓝题</td>\n</tr>\n<tr>\n<td>CF1051F</td>\n<td><a href=\"https://codeforces.com/contest/1051/problem/F\">The Shortest Statement</a></td>\n<td>m-n&lt;=20。每次查两个点的最短路</td>\n<td>2400/蓝题</td>\n</tr>\n<tr>\n<td>CF1328E</td>\n<td><a href=\"https://codeforces.com/problemset/problem/1328/E\">Tree Queries</a></td>\n<td>是否存在一条到根的路径，查询一组节点到这一条路径距离不超过1</td>\n<td>1900/蓝题</td>\n</tr>\n<tr>\n<td>P10289</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P10289\">小杨的旅游</a></td>\n<td>查询树上两点距离，会有多个传送门</td>\n<td>绿题</td>\n</tr>\n<tr>\n<td>P10113</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P10113\">大量的工作沟通</a></td>\n<td>查询一组节点最大编号的公共祖先</td>\n<td>绿题</td>\n</tr>\n<tr>\n<td>P13019</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P13019\">树上旅行</a></td>\n<td>走沿着父节点走或编号最小的儿子走</td>\n<td>绿题</td>\n</tr>\n<tr>\n<td>P4281</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P4281\">紧急集合 / 聚会</a></td>\n<td>三个点最近的点</td>\n<td>绿题</td>\n</tr>\n<tr>\n<td>CF832D</td>\n<td><a href=\"https://codeforces.com/problemset/problem/832/D\">Misha, Grisha and Underground</a></td>\n<td>最长的a-&gt;c,b-&gt;c交集部分</td>\n<td>1900/绿题</td>\n</tr>\n<tr>\n<td>2491</td>\n<td><a href=\"https://loj.ac/p/2491\">求和</a></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>P3938</td>\n<td><a href=\"https://www.luogu.com.cn/problem/P3938\">斐波那契</a></td>\n<td>树结构是斐波那契。给两个数字，求lca</td>\n<td>绿题</td>\n</tr>\n</tbody>\n</table>\n";
